const ANTI = [
  q('anti_radikalisme', 2, 'Ciri sikap radikal yang dapat mengarah pada ekstremisme kekerasan antara lain …', ['intoleran, fanatik, eksklusif, dan membenarkan kekerasan untuk tujuan', 'kritis terhadap kebijakan pemerintah', 'aktif berorganisasi di masyarakat', 'taat menjalankan agama', 'menolak membeli produk tertentu'], 0, { pola: 'BNPT menyebut ciri radikalisme: intoleran, fanatik, eksklusif, revolusioner (membenarkan kekerasan).', langkah: 'Kritik, organisasi, dan ketaatan beragama adalah hak dan bukan radikalisme.', jebakan: 'Menyamakan religiusitas atau sikap kritis dengan radikalisme.', cepat: 'Radikal = intoleran + membenarkan kekerasan.' }),
  q('anti_radikalisme', 3, 'Badan Nasional Penanggulangan Terorisme (BNPT) dibentuk berdasarkan …', ['Perpres No. 46 Tahun 2010', 'UU No. 5 Tahun 2018', 'Perpres No. 7 Tahun 2021', 'UU No. 15 Tahun 2003', 'Keppres No. 28 Tahun 2006'], 0, { pola: 'Perpres 46/2010 membentuk BNPT; UU 15/2003 jo. UU 5/2018 mengatur pemberantasan tindak pidana terorisme; Perpres 7/2021 RAN PE.', langkah: 'Bedakan peraturan pembentukan lembaga dari UU pidana dan rencana aksi.', jebakan: 'UU 5/2018 memperkuat peran BNPT tetapi bukan dasar pembentukannya.', cepat: 'BNPT = Perpres 46/2010.' }),
  q('anti_radikalisme', 3, 'Rencana Aksi Nasional Pencegahan dan Penanggulangan Ekstremisme Berbasis Kekerasan yang Mengarah pada Terorisme (RAN PE) ditetapkan melalui …', ['Perpres No. 7 Tahun 2021', 'UU No. 5 Tahun 2018', 'Perpres No. 46 Tahun 2010', 'PP No. 77 Tahun 2019', 'TAP MPR No. XVIII/MPR/1998'], 0, { pola: 'Perpres 7/2021 menetapkan RAN PE 2020 sampai 2024 dengan pilar pencegahan, penegakan hukum, dan kemitraan.', langkah: 'PP 77/2019 mengatur pencegahan terorisme dan perlindungan aparat.', jebakan: 'Nomor peraturan berdekatan; ingat RAN PE = 7/2021.', cepat: 'RAN PE = Perpres 7/2021.' }, 'Periode RAN PE dan peraturan lanjutannya dapat berubah; cek peraturan terbaru.'),
  q('anti_radikalisme', 1, 'Seorang rekan kerja membagikan konten di grup kantor yang mengajak membenci kelompok tertentu. Sikap yang tepat adalah …', ['tidak ikut menyebarkan, menegur secara santun, dan melaporkan jika berlanjut', 'ikut membagikan agar tidak dikucilkan', 'diam saja karena bukan urusan kerja', 'membalas dengan konten kebencian terhadap kelompok lain', 'keluar dari grup tanpa berkata apa-apa'], 0, { pola: 'Pencegahan radikalisme dimulai dari lingkungan terdekat: menolak menyebarkan, menegur, melapor.', langkah: 'Diam dan keluar grup membiarkan konten bekerja.', jebakan: 'Membalas kebencian memperkuat polarisasi.', cepat: 'Tidak sebar, tegur, lapor.' }),
  q('anti_radikalisme', 2, 'Sikap beragama yang mengambil jalan tengah, toleran, antikekerasan, dan menghargai tradisi lokal disebut …', ['moderasi beragama', 'sekularisme', 'sinkretisme', 'fundamentalisme', 'agnostisisme'], 0, { pola: 'Moderasi beragama (Kementerian Agama) memiliki empat indikator: komitmen kebangsaan, toleransi, antikekerasan, akomodatif terhadap budaya lokal.', langkah: 'Sekularisme memisahkan agama dari negara; sinkretisme mencampur ajaran.', jebakan: 'Mengira moderasi berarti mengurangi ketaatan.', cepat: 'Jalan tengah, toleran, antikekerasan = moderasi.' }),
  q('anti_radikalisme', 2, 'Perbedaan antara radikalisme dan terorisme adalah …', ['radikalisme adalah paham atau sikap, terorisme adalah tindakan kekerasan yang menimbulkan teror', 'radikalisme selalu bersenjata, terorisme tidak', 'radikalisme dilakukan negara, terorisme oleh warga', 'keduanya sama persis', 'terorisme adalah paham, radikalisme adalah tindakan'], 0, { pola: 'Radikalisme berada pada tataran gagasan; terorisme (UU 5/2018) adalah perbuatan kekerasan atau ancaman yang menimbulkan suasana teror secara meluas.', langkah: 'Tidak semua orang berpaham radikal melakukan terorisme, tetapi terorisme biasanya diawali radikalisasi.', jebakan: 'Opsi E membalik keduanya.', cepat: 'Paham vs perbuatan.' }),
  q('anti_radikalisme', 1, 'Anda diundang ke grup daring eksklusif yang menyatakan menolak Pancasila dan mengajak “berjuang dengan cara apa pun”. Tindakan yang tepat adalah …', ['menolak bergabung dan melaporkan ke pihak berwenang', 'bergabung untuk memantau diam-diam', 'bergabung karena hanya grup diskusi', 'mengundang teman agar ramai', 'membiarkan tanpa tindakan'], 0, { pola: 'Ajakan menolak dasar negara dengan “cara apa pun” adalah indikasi ekstremisme kekerasan; laporkan.', langkah: 'Memantau sendiri berisiko dan bukan kewenangan warga.', jebakan: '“Hanya diskusi” menutupi ajakan.', cepat: 'Tolak dan lapor.' }),
  q('anti_radikalisme', 3, 'Program yang ditujukan kepada orang yang telah terpapar paham radikal agar meninggalkan paham tersebut disebut …', ['deradikalisasi', 'kontra-radikalisasi', 'moderasi', 'rehabilitasi sosial umum', 'asimilasi'], 0, { pola: 'Deradikalisasi ditujukan kepada yang sudah terpapar (termasuk narapidana terorisme); kontra-radikalisasi adalah pencegahan bagi masyarakat umum.', langkah: 'Prefiks “de-” menunjuk pelepasan dari sesuatu yang sudah ada.', jebakan: 'Kontra-radikalisasi tampak serupa, tetapi sasarannya masyarakat yang belum terpapar.', cepat: 'Sudah terpapar = deradikalisasi; belum = kontra.' })
];

